var p = msg.payload;
if (!p) return null;

// Output 1: Gauge dự báo mực nước 5m (pure number)
var msgGauge5m = {
    payload: p.predicted_level_5m,
    topic: 'Dự báo +5m'
};

// Output 2: Gauge xác suất ngập 30m (%) (pure number)
var msgGauge30m = {
    payload: p.prob_flood_30m,
    topic: 'Xác suất ngập +30m (%)'
};

// Output 3: Trạng thái đa tầng (Object for UI Template)
var msgStatus = {
    payload: {
        status_color: p.status_color || '#2ecc71',
        predicted_status: p.predicted_status || 'AN TOÀN',
        predicted_fill_5m: p.predicted_fill_5m || 0,
        status_30m_color: p.status_30m_color || '#2ecc71',
        status_30m: p.status_30m || 'AN TOÀN THOÁT NƯỚC',
        prob_flood_30m: p.prob_flood_30m || 0,
        current_level: p.current_level || 0,
        predicted_level_15m: p.predicted_level_15m || 0,
        predicted_level_30m: p.predicted_level_30m || 0,
        predicted_level_60m: p.predicted_level_60m || 0
    }
};

// Output 4: Khuyến nghị điều phối giao thông (Object for UI Template)
var warnColor = p.early_warning ? '#e74c3c' : (p.prob_flood_30m >= 50 ? '#f39c12' : '#2ecc71');
var msgTraffic = {
    payload: {
        traffic_color: warnColor,
        traffic_advisory: p.traffic_advisory || 'Lưu lượng thoát ổn định.'
    }
};

// Output 5: Biểu đồ đa đường (Actual, +5m, +30m, +60m)
var msgChartActual = { topic: '1. Mực nước thực tế (cm)', payload: p.current_level };
var msgChart5m     = { topic: '2. Dự báo AI +5m (cm)',   payload: p.predicted_level_5m };
var msgChart30m    = { topic: '3. Dự báo AI +30m (cm)',  payload: p.predicted_level_30m };
var msgChart60m    = { topic: '4. Dự báo AI +60m (cm)',  payload: p.predicted_level_60m };

// Output 6: Telegram early warning alert
var msgTg = null;
if (p.early_warning) {
    var lastAlert = flow.get('last_ai_alert_time') || 0;
    var now = Date.now();
    if (now - lastAlert > 180000) {
        flow.set('last_ai_alert_time', now);
        var tgChatId = global.get('telegram_chat_id');
        msgTg = {
            payload: {
                chatId: tgChatId,
                type: 'message',
                content: '🚨 *CẢNH BÁO SỚM ĐIỀU PHỐI GIAO THÔNG (AI MULTI-HORIZON)*\n\n' +
                         '📍 *Vị trí:* Cống 1 & Điểm trũng mặt đường\n' +
                         '🌊 *Mực nước hiện tại:* ' + p.current_level + ' cm (' + p.current_fill + '%)\n' +
                         '🔮 *Dự báo +5 phút:* ' + p.predicted_level_5m + ' cm\n' +
                         '🔮 *Dự báo +30 phút:* ' + p.predicted_level_30m + ' cm (*Xác suất ngập: ' + p.prob_flood_30m + '%*)\n' +
                         '🔮 *Dự báo +60 phút:* ' + p.predicted_level_60m + ' cm\n\n' +
                         '📢 *Khuyến nghị:* ' + p.traffic_advisory + '\n\n' +
                         '_(Tích hợp Radar Nowcasting & Cảm biến IoT UET)_'
            }
        };
    }
}

return [msgGauge5m, msgGauge30m, msgStatus, msgTraffic, [msgChartActual, msgChart5m, msgChart30m, msgChart60m], msgTg];

// flood/<id>/level → nhận diện loại node theo nội dung: có "L" & "m" = node cống, có "h" = node đường.
// Nhờ vậy thêm node mới (cong2, duong2...) không phải sửa flow.
const id = String(msg.topic).split('/')[1];
const p = msg.payload;
if (!id || typeof p !== 'object' || p === null) {
    node.warn('Payload không hợp lệ: ' + msg.topic);
    return null;
}
msg.node = id;
if (p.L !== undefined && p.m !== undefined) return [msg, null];
if (p.h !== undefined) return [null, msg];
node.warn('Không nhận ra loại node: ' + msg.topic);
return null;

// Edge IT cho node cống:
//  - trung bình trượt 5 mẫu gần nhất
//  - tốc độ dâng v = (m_tb - m_tb cách đây 1 phút) / Δt   (cm/phút)
//  - phân mức có hysteresis: lên mức ngay, hạ mức dùng ngưỡng thấp hơn + giữ tối thiểu 30 s
const T = {
    Y_L: 50, Y_V: 2,              // VÀNG nếu L > 50% hoặc v ≥ 2 cm/phút
    R_L: 80, R_L2: 60, R_V: 5,    // ĐỎ   nếu L > 80% hoặc (L > 60% và v ≥ 5 cm/phút)
    Y_L_DN: 45, Y_V_DN: 1.5,      // ngưỡng hạ mức (vùng chết)
    R_L_DN: 75, R_L2_DN: 55, R_V_DN: 4,
    HOLD_MS: 30000,
    WINDOW_MS: 60000,
    AVG_N: 5
};
const LV = ['green', 'yellow', 'red'];
const VN = ['🟢 XANH – theo dõi', '🟡 VÀNG – theo dõi sát', '🔴 ĐỎ – yêu cầu bật bơm/mở van'];

const id = msg.node, p = msg.payload;
const m = Number(p.m), L = Number(p.L);
if (!isFinite(m) || !isFinite(L)) { node.warn(id + ': thiếu m/L'); return null; }

const now = Date.now();
const all = flow.get('drain_state') || {};
const st = all[id] || { mBuf: [], lBuf: [], hist: [], level: 0, since: now };

st.mBuf.push(m); st.lBuf.push(L);
if (st.mBuf.length > T.AVG_N) { st.mBuf.shift(); st.lBuf.shift(); }
const avg = a => a.reduce((s, x) => s + x, 0) / a.length;
const mAvg = avg(st.mBuf), lAvg = avg(st.lBuf);

st.hist.push([now, mAvg]);
while (st.hist.length && now - st.hist[0][0] > 3 * T.WINDOW_MS) st.hist.shift();
let ref = null;
for (let i = st.hist.length - 1; i >= 0; i--) {
    if (now - st.hist[i][0] >= T.WINDOW_MS) { ref = st.hist[i]; break; }
}
// Mới khởi động, chưa đủ 1 phút: tạm dùng mẫu cũ nhất nếu đã cách ≥ 20 s
if (!ref && st.hist.length && now - st.hist[0][0] >= 20000) ref = st.hist[0];
let v = ref ? (mAvg - ref[1]) / ((now - ref[0]) / 60000) : 0;
v = Math.round(Math.max(-100, Math.min(100, v)) * 10) / 10;

function up(L, v)   { if (L > T.R_L || (L > T.R_L2 && v >= T.R_V)) return 2; if (L > T.Y_L || v >= T.Y_V) return 1; return 0; }
function keep(L, v) { if (L > T.R_L_DN || (L > T.R_L2_DN && v >= T.R_V_DN)) return 2; if (L > T.Y_L_DN || v >= T.Y_V_DN) return 1; return 0; }

const cur = st.level;
let next = cur;
const u = up(lAvg, v);
if (u > cur) {
    next = u;                                         // nguy hiểm hơn → lên mức ngay
} else {
    const k = keep(lAvg, v);
    if (k < cur && now - st.since >= T.HOLD_MS) next = k;
}
if (next !== cur) { st.level = next; st.since = now; }
all[id] = st;
flow.set('drain_state', all);

const r1 = x => Math.round(x * 10) / 10;
const data = { m: r1(mAvg), L: r1(lAvg), v, v_ready: !!ref, d: p.d };
const out = { topic: 'level', node: id, kind: 'drain', level: LV[st.level], data };
if (id !== 'cong1') return [out, null, null, null, null, null];

const vText = (v >= 0 ? '+' : '') + v.toFixed(1) + ' cm/phút' + (ref ? '' : ' (đang tích luỹ)');
return [
    out,
    { payload: data.L },
    { payload: VN[st.level] },
    { payload: vText },
    { payload: data.m + ' cm' },
    [{ topic: 'Mực nước (cm)', payload: data.m }, { topic: 'Độ đầy (%)', payload: data.L }]
];

// Node đường tự phân mức (để vẫn cảnh báo khi mất mạng) → Edge chỉ lấy mức node gửi lên.
const LV = ['green', 'yellow', 'red'];
const VN = {
    green:  '🟢 XANH – đi lại bình thường',
    yellow: '🟡 VÀNG – xe máy đi chậm, cẩn trọng',
    red:    '🔴 ĐỎ – không nên đi xe máy'
};
const id = msg.node, p = msg.payload;
const h = Number(p.h);
if (!isFinite(h)) { node.warn(id + ': thiếu h'); return null; }

let level = p.muc;
if (!LV.includes(level)) level = h > 20 ? 'red' : h >= 10 ? 'yellow' : 'green';   // dự phòng

const r1 = x => Math.round(x * 10) / 10;
const data = { h: r1(h), stable: p.stable !== false, buzzer_muted: !!p.buzzer_muted, d: p.d };
const out = { topic: 'level', node: id, kind: 'road', level, data };
if (id !== 'duong1') return [out, null, null, null, null];

const buzzer = level === 'red'
    ? (data.buzzer_muted ? '🔇 Đã tắt thủ công' : '🔊 Đang kêu')
    : 'Tắt (chỉ kêu ở mức ĐỎ)';
const lvlText = VN[level] + (data.stable ? '' : ' · đang chờ ổn định');
return [out, { payload: data.h }, { payload: lvlText }, { payload: buzzer },
        { topic: 'Độ sâu ngập (cm)', payload: data.h }];

// flood/<id>/status: "online" khi node kết nối, "offline" do broker phát Last Will khi node rớt.
const id = String(msg.topic).split('/')[1];
const s = String(msg.payload).trim().toLowerCase();
if (s !== 'online' && s !== 'offline') return null;
const txt = s === 'online' ? '🟢 ONLINE' : '🔴 OFFLINE';
const out = { topic: 'conn', node: id, payload: s };
return [out, id === 'cong1' ? { payload: txt } : null, id === 'duong1' ? { payload: txt } : null];

// Heartbeat thiết bị (fw, ip, rssi, uptime, lỗi đo, cấu hình đang chạy) → bảng thiết bị.
// Đồng thời điền cấu hình thực tế của node vào form (chỉ khi cấu hình thay đổi, để không xoá chữ đang gõ).
const id = String(msg.topic).split('/')[1];
if (typeof msg.payload !== 'object' || !msg.payload) return null;
const info = flow.get('info') || {};
info[id] = Object.assign({}, msg.payload, { received: Date.now() });
flow.set('info', info);

const cfg = msg.payload.cfg;
if (!cfg) return null;
const shown = flow.get('form_prefill') || {};
const key = JSON.stringify(cfg);
if (shown[id] === key) return null;
shown[id] = key;
flow.set('form_prefill', shown);
const o = { payload: cfg };
return [id === 'cong1' ? o : null, id === 'duong1' ? o : null];

// Sự kiện từ node (hiệu chuẩn, áp dụng/từ chối cấu hình, còi...) → nhật ký.
// Sau khi hiệu chuẩn, cập nhật lại cấu hình retained trên broker để lần kết nối sau
// broker không ghi đè giá trị vừa đo.
const id = String(msg.topic).split('/')[1];
const e = msg.payload || {};
let republish = null, text;

switch (e.event) {
    case 'calibrated': {
        text = `📏 ${id}: hiệu chuẩn xong, ${e.key} = ${e.value} cm`;
        const cfgs = flow.get('cfg') || {};
        const c = Object.assign({}, cfgs[id] || {});
        c[e.key] = e.value;
        cfgs[id] = c;
        flow.set('cfg', cfgs);
        republish = { topic: `flood/${id}/config`, payload: c, retain: true, qos: 1 };
        break;
    }
    case 'calibrate_failed': text = `⚠️ ${id}: hiệu chuẩn thất bại (${e.reason || 'không đo được'})`; break;
    case 'config_applied':   text = `⚙️ ${id}: đã áp dụng cấu hình mới`; break;
    case 'config_rejected':  text = `⛔ ${id}: từ chối cấu hình – ${e.reason || ''}`; break;
    case 'buzzer':           text = `${e.muted ? '🔇' : '🔔'} ${id}: còi ${e.muted ? 'đã tắt' : 'sẵn sàng kêu lại'}`; break;
    case 'rebooting':        text = `🔄 ${id}: đang khởi động lại`; break;
    default:                 text = `${id}: ${e.event || 'sự kiện'} ${e.reason || ''}`;
}
return [republish, { payload: { t: Date.now(), text } }];

// Node-RED cũng subscribe flood/+/config (retained) để khôi phục bản sao cấu hình khi khởi động lại.
const id = String(msg.topic).split('/')[1];
if (typeof msg.payload !== 'object' || !msg.payload) return null;
const cfgs = flow.get('cfg') || {};
cfgs[id] = msg.payload;
flow.set('cfg', cfgs);
return null;

// ═══════════════════════════════════════════════════════════════════════════
// Bộ quyết định cảnh báo (Edge IT)
//  - Gửi Telegram mỗi khi mức của một node thay đổi (cả lên và xuống)
//  - Cống lên ĐỎ → mở "sự cố": gửi YÊU CẦU bật bơm/mở van kèm nút Xác nhận
//  - Chưa xác nhận sau 10 phút mà cống vẫn ĐỎ → nhắc lại
//  - Cống ĐỎ + đường ≥ VÀNG → "Ngập đang lan rộng" + thời gian báo trước
//  - Node offline (Last Will) hoặc im lặng > 30 s → báo mất kết nối
// Đầu vào (msg.topic): level | conn | tick | ack | query
// Đầu ra: 1 Telegram · 2 tình trạng chung · 3 yêu cầu vận hành · 4 nhật ký
//         5 trạng thái tổng hợp → flood/edge/state (retained, bridge lên cloud)
//         6 bản ghi sự cố đã đóng → flood/edge/incident (cloud lưu để thống kê)
// ═══════════════════════════════════════════════════════════════════════════
const REMIND_MS = 10 * 60 * 1000;
const STALE_MS  = 30 * 1000;
const LVN  = { green: '🟢 XANH', yellow: '🟡 VÀNG', red: '🔴 ĐỎ' };
const RANK = { green: 0, yellow: 1, red: 2 };

const now = Date.now();
const chatId = global.get('telegram_chat_id');
const reg = flow.get('reg') || {};
const incidents = flow.get('incidents') || {};
const devInfo = flow.get('info') || {};
const tg = [], logs = [], closed = [];

const hhmm = t => new Date(t).toLocaleTimeString('vi-VN', { hour12: false, timeZone: 'Asia/Ho_Chi_Minh' });
const dur = ms => { const s = Math.max(0, Math.round(ms / 1000)); return s < 60 ? s + ' giây' : Math.floor(s / 60) + ' phút ' + (s % 60) + ' giây'; };
const md = s => String(s).replace(/([_*`\[])/g, '\\$1');
const sign = v => (v >= 0 ? '+' : '') + v;
function kindOf(id) {
    const r = reg[id] || {}, i = devInfo[id] || {};
    return r.kind || (i.role === 'drain' ? 'drain' : i.role === 'road' ? 'road' : '');
}
const label = id => ({ drain: 'Cống ', road: 'Đường ' }[kindOf(id)] || 'Node ') + id;
const entry = id => (reg[id] = reg[id] || { id });

function send(text, keyboard, to) {
    const pl = { chatId: to || chatId, type: 'message', content: text };
    if (keyboard) pl.options = { reply_markup: JSON.stringify({ inline_keyboard: keyboard }) };
    tg.push({ payload: pl });
}
function log(text) { logs.push({ payload: { t: now, text } }); }
const ackButton = inc => [[{ text: '✅ Đã xử lý (bật bơm / mở van)', callback_data: 'ack:' + inc.key }]];

function closeIncident(id) {
    const inc = incidents[id];
    if (!inc) return '';
    delete incidents[id];
    closed.push({ topic: 'flood/edge/incident', qos: 1, retain: false, payload: {
        key: inc.key, node: id, start: inc.start, end: now, duration_s: Math.round((now - inc.start) / 1000),
        ack: inc.ack, ack_by: inc.ack_by || null, ack_at: inc.ack_at || null,
        response_s: inc.ack ? Math.round((inc.ack_at - inc.start) / 1000) : null,
        reminders: inc.reminders, max_L: inc.max_L || null, lead_s: inc.lead_s || null } });
    const ackTxt = inc.ack ? `đã xác nhận bởi ${md(inc.ack_by)} sau ${dur(inc.ack_at - inc.start)}` : 'CHƯA có xác nhận xử lý';
    log(`Đóng sự cố ${id}: mức đỏ kéo dài ${dur(now - inc.start)}, ${inc.ack ? 'đã' : 'chưa'} xác nhận`);
    return `\n📋 Sự cố mức đỏ kéo dài ${dur(now - inc.start)}, ${ackTxt}.`;
}

function drainChanged(id, prev, cur, d) {
    const info = `Mực nước ${d.L}% (${d.m} cm), tốc độ dâng ${sign(d.v)} cm/phút`;
    if (cur === 'red') {
        const inc = { key: id + '-' + now, node: id, start: now, last_sent: now, reminders: 0, ack: false, max_L: d.L };
        incidents[id] = inc;
        send(`🔴 *KHẨN – ${label(id)}*\n${info}.\n👉 *YÊU CẦU bật bơm / mở van* chuyển dòng sang trục cống hoặc hồ điều hòa còn dung tích.\nBấm nút bên dưới sau khi đã xử lý.`, ackButton(inc));
        log(`${label(id)} lên ĐỎ (${d.L}%, ${sign(d.v)} cm/ph) → gửi yêu cầu vận hành`);
        return;
    }
    const summary = prev === 'red' ? closeIncident(id) : '';
    if (cur === 'yellow') {
        send(`🟡 *THEO DÕI – ${label(id)}*\n${info}.${summary}`);
        log(`${label(id)} ${prev === 'red' ? 'hạ xuống' : 'lên'} VÀNG (${d.L}%, ${sign(d.v)} cm/ph)`);
    } else {
        send(`🟢 *${label(id)} trở về an toàn*\n${info}.${summary}`);
        log(`${label(id)} trở về XANH (${d.L}%)`);
    }
}

function roadChanged(id, prev, cur, d) {
    const text = {
        red:    `🔴 *KHẨN – ${label(id)} ngập ${d.h} cm*\nKhông nên đi xe máy. Đèn đỏ và còi đang bật tại chỗ.`,
        yellow: prev === 'red'
            ? `🟡 *${label(id)}* giảm còn ${d.h} cm – xe máy đi chậm, cẩn trọng.`
            : `🟡 *THEO DÕI – ${label(id)} ngập ${d.h} cm*\nXe máy đi chậm, cẩn trọng.`,
        green:  `🟢 *${label(id)} hết ngập* (${d.h} cm) – đi lại bình thường.`
    }[cur];
    send(text);
    log(`${label(id)}: ${LVN[prev]} → ${LVN[cur]} (${d.h} cm)`);
}

function setOnline(id, on) {
    const r = entry(id);
    const was = r.online;
    r.online = on;
    if (!on && was !== false) {
        send(`⚠️ *Mất kết nối ${label(id)}*\nBroker phát Last Will lúc ${hhmm(now)}. Dữ liệu tại điểm này đang không được cập nhật.`);
        log(`${label(id)} OFFLINE`);
    }
    if (on && was === false) {
        send(`✅ ${label(id)} đã kết nối lại.`);
        log(`${label(id)} ONLINE trở lại`);
    }
}

function checkSpread() {
    const vals = Object.values(reg).filter(r => r.online !== false);
    const redDrains = vals.filter(r => r.kind === 'drain' && r.level === 'red');
    const wetRoads  = vals.filter(r => r.kind === 'road' && RANK[r.level] >= 1);
    const spread = redDrains.length > 0 && wetRoads.length > 0;
    const was = flow.get('spread') || false;
    if (spread && !was) {
        const firstRed = Math.min(...redDrains.map(r => (incidents[r.id] || {}).start || now));
        const lead = now - firstRed;
        flow.set('last_lead_ms', lead);
        for (const r of redDrains) if (incidents[r.id] && !incidents[r.id].lead_s) incidents[r.id].lead_s = Math.round(lead / 1000);
        send(`🌊 *NGẬP ĐANG LAN RỘNG*\n${redDrains.map(r => label(r.id)).join(', ')} ở mức ĐỎ và ${wetRoads.map(r => label(r.id) + ' ngập ' + r.data.h + ' cm').join(', ')}.\n⏱ Cống đã báo đỏ trước ${dur(lead)} so với lúc nước lên mặt đường.\n👉 Ưu tiên điều phối bơm và phân luồng giao thông.`);
        log(`Ngập lan rộng – cống báo trước ${dur(lead)}`);
    } else if (!spread && was) {
        log('Hết tình trạng ngập lan rộng');
    }
    flow.set('spread', spread);
    return spread;
}

switch (msg.topic) {
    case 'level': {
        const id = msg.node;
        const r = entry(id);
        r.kind = msg.kind;
        r.data = msg.data;
        r.last_seen = now;
        if (r.online === false) setOnline(id, true);      // có dữ liệu ⇒ đã online
        else r.online = true;
        if (r.stale) {
            r.stale = false;
            send(`✅ ${label(id)} gửi dữ liệu trở lại.`);
            log(`${label(id)} có dữ liệu trở lại`);
        }
        const prev = r.level || 'green';
        r.level = msg.level;
        if (msg.kind === 'drain' && incidents[id]) incidents[id].max_L = Math.max(incidents[id].max_L || 0, msg.data.L);
        if (prev !== msg.level) (msg.kind === 'drain' ? drainChanged : roadChanged)(id, prev, msg.level, msg.data);
        break;
    }
    case 'conn':
        setOnline(msg.node, msg.payload === 'online');
        break;

    case 'tick': {
        for (const r of Object.values(reg)) {
            if (r.online !== false && r.last_seen && !r.stale && now - r.last_seen > STALE_MS) {
                r.stale = true;
                send(`⚠️ *${label(r.id)} không gửi dữ liệu* trong ${dur(now - r.last_seen)} (kết nối vẫn mở – kiểm tra cảm biến).`);
                log(`${label(r.id)} không có dữ liệu mới`);
            }
        }
        for (const inc of Object.values(incidents)) {
            const r = reg[inc.node];
            if (!inc.ack && r && r.level === 'red' && now - inc.last_sent >= REMIND_MS) {
                inc.reminders++;
                inc.last_sent = now;
                send(`⏰ *NHẮC LẠI lần ${inc.reminders} – ${label(inc.node)}*\nCống vẫn ở mức ĐỎ sau ${dur(now - inc.start)} mà chưa có xác nhận xử lý.\nHiện tại: ${r.data.L}%, dâng ${sign(r.data.v)} cm/phút.\n👉 *YÊU CẦU bật bơm / mở van.*`, ackButton(inc));
                log(`Nhắc lại yêu cầu vận hành ${inc.node} (lần ${inc.reminders})`);
            }
        }
        break;
    }
    case 'ack': {
        const by = msg.by || 'Người quản lý', src = msg.source || 'Dashboard';
        const pending = Object.values(incidents).filter(i => !i.ack && (!msg.key || i.key === msg.key));
        let reply;
        if (!pending.length) {
            const already = msg.key && Object.values(incidents).some(i => i.key === msg.key);
            reply = already ? 'Sự cố này đã được xác nhận trước đó.' : 'Không còn yêu cầu nào đang chờ (sự cố có thể đã đóng).';
            if (src === 'Dashboard') log('Bấm xác nhận nhưng không có yêu cầu nào đang chờ');
        } else {
            for (const inc of pending) {
                inc.ack = true; inc.ack_at = now; inc.ack_by = by;
                send(`✅ *${md(by)}* (qua ${src}) đã xác nhận xử lý sự cố ${label(inc.node)} lúc ${hhmm(now)} – phản hồi sau ${dur(now - inc.start)}.`);
                log(`${by} xác nhận xử lý ${inc.node} qua ${src}, phản hồi sau ${dur(now - inc.start)}`);
            }
            reply = 'Đã ghi nhận xác nhận. Cảm ơn!';
        }
        if (msg.cb && msg.cb.id) {
            tg.push({ payload: { chatId: msg.cb.chatId, type: 'answerCallbackQuery', callbackQueryId: msg.cb.id, content: reply } });
        }
        break;
    }
    case 'query': {
        const lines = Object.values(reg).sort((a, b) => a.id.localeCompare(b.id)).map(r => {
            const conn = r.online === false ? '🔴 offline' : r.stale ? '🟠 không có dữ liệu' : '🟢 online';
            const val = !r.data ? 'chưa có dữ liệu'
                : r.kind === 'drain' ? `${r.data.L}% (${r.data.m} cm), dâng ${sign(r.data.v)} cm/ph`
                : `ngập ${r.data.h} cm`;
            return `${LVN[r.level] || '⚪'} ${label(r.id)}: ${val} · ${conn}`;
        });
        const open = Object.values(incidents).map(i =>
            `• ${label(i.node)}: từ ${hhmm(i.start)}, ${i.ack ? 'đã xác nhận bởi ' + md(i.ack_by) : 'CHƯA xác nhận'}`);
        send(`📊 *Trạng thái lúc ${hhmm(now)}*\n${lines.join('\n') || 'Chưa có node nào.'}` +
             (open.length ? '\n\n🚨 Yêu cầu vận hành:\n' + open.join('\n') : ''), null, msg.chatId);
        break;
    }
    default:
        return null;
}

const spread = checkSpread();
const vals = Object.values(reg);
const worst = Math.max(0, ...vals.filter(r => r.online !== false).map(r => RANK[r.level] || 0));
const offline = vals.filter(r => r.online === false || r.stale).map(r => r.id);
let combined = spread ? '🌊 NGẬP ĐANG LAN RỘNG – cống đỏ và đường đã ngập'
    : ['🟢 AN TOÀN', '🟡 CẦN THEO DÕI', '🔴 NGUY HIỂM'][worst];
if (offline.length) combined += ' · ⚠️ mất kết nối: ' + offline.join(', ');

const open = Object.values(incidents);
const incText = !open.length ? 'Không có yêu cầu nào'
    : open.map(i => `${label(i.node)}: bật bơm/mở van (từ ${hhmm(i.start)}) – ` +
        (i.ack ? `✅ ${i.ack_by} đã xác nhận` : '⏳ chờ xác nhận' + (i.reminders ? `, đã nhắc ${i.reminders} lần` : ''))).join(' | ');

flow.set('reg', reg);
flow.set('incidents', incidents);
const state = {
    ts: now, combined, worst: ['green', 'yellow', 'red'][worst], spread, lead_ms: flow.get('last_lead_ms') || null,
    nodes: Object.fromEntries(vals.map(r => [r.id, {
        kind: r.kind || kindOf(r.id) || null, level: r.level || null, online: r.online !== false,
        stale: !!r.stale, last_seen: r.last_seen || null, data: r.data || null }])),
    incidents: open.map(i => ({ key: i.key, node: i.node, start: i.start, ack: i.ack, ack_by: i.ack_by || null,
        ack_at: i.ack_at || null, reminders: i.reminders, max_L: i.max_L || null }))
};
return [tg.length ? tg : null, { payload: combined }, { payload: incText }, logs.length ? logs : null,
        { topic: 'flood/edge/state', payload: state, retain: true, qos: 0 }, closed.length ? closed : null];

// Chặn tin khi chưa cấu hình TELEGRAM_CHAT_ID (tránh lỗi node telegram sender).
const p = msg.payload;
if (!p || !p.chatId) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'Bỏ qua: chưa đặt TELEGRAM_CHAT_ID' });
    return null;
}
node.status({ fill: 'green', shape: 'dot', text: 'Gửi lúc ' + new Date().toLocaleTimeString('vi-VN', { hour12: false }) });
return msg;

// Người quản lý bấm nút "Đã xử lý" trong tin nhắn Telegram (callback_data = "ack:<mã sự cố>").
// Chỉ chấp nhận xác nhận từ chat đã cấu hình (TELEGRAM_CHAT_ID).
const p = msg.payload || {};
const data = String(p.content || '');
if (!data.startsWith('ack:')) return null;

const allowed = String(global.get('telegram_chat_id') || '');
if (allowed && String(p.chatId) !== allowed) {
    node.warn('Bỏ qua xác nhận từ chat không được phép: ' + p.chatId);
    return null;
}
const from = (msg.originalMessage && msg.originalMessage.from) || p.from || {};
const by = [from.first_name, from.last_name].filter(Boolean).join(' ') || from.username || 'Người quản lý';
return { topic: 'ack', key: data.slice(4), by, source: 'Telegram', cb: { chatId: p.chatId, id: p.callbackQueryId } };

// Lệnh /status: ai nhắn bot cũng xem được trạng thái (thông tin công khai cho người dân).
const p = msg.payload || {};
if (!p.chatId) return null;
return { topic: 'query', chatId: p.chatId };

// Nhật ký sự kiện: hiển thị trên dashboard (30 dòng gần nhất) và gửi lên cloud (flood/edge/log).
const e = msg.payload;
if (!e || !e.text) return null;
const list = flow.get('eventlog') || [];
list.unshift({
    time: new Date(e.t || Date.now()).toLocaleTimeString('vi-VN', { hour12: false, timeZone: 'Asia/Ho_Chi_Minh' }),
    text: e.text
});
while (list.length > 30) list.pop();
flow.set('eventlog', list);
return [{ payload: list }, { topic: 'flood/edge/log', qos: 1, retain: false, payload: { t: e.t || Date.now(), text: e.text } }];

// Lệnh từ Web console trên cloud, đi xuống qua MQTT bridge (chỉ topic flood/cloud/#).
// Cloud KHÔNG điều khiển node trực tiếp: gateway nhận, kiểm tra như lệnh từ dashboard rồi mới chuyển xuống node.
//   flood/cloud/ack            {key?, by}        → xác nhận xử lý sự cố
//   flood/cloud/config/<id>    {khoá: số,...}    → form cấu hình (kiểm tra, publish retained cục bộ)
//   flood/cloud/cmd/<id>       {cmd}             → calibrate | report
//   flood/cloud/alarm/<id>     "off" | "on"      → tắt / bật lại còi
const parts = String(msg.topic).split('/');
const kind = parts[2], id = parts[3];
const p = msg.payload;
const validId = /^[a-z0-9_-]{1,20}$/.test(id || '');

if (kind === 'ack') {
    const o = (typeof p === 'object' && p) || {};
    return [{ topic: 'ack', key: o.key || undefined, by: String(o.by || 'Quản lý').slice(0, 60), source: 'Web' }, null, null];
}
if (kind === 'config' && validId && typeof p === 'object' && p) {
    return [null, { topic: id, payload: p, source: 'Web' }, null];
}
if (kind === 'cmd' && validId && p && ['calibrate', 'report'].includes(p.cmd)) {
    return [null, null, { topic: `flood/${id}/cmd`, payload: { cmd: p.cmd }, source: 'Web' }];
}
if (kind === 'alarm' && validId && (p === 'off' || p === 'on')) {
    return [null, null, { topic: `flood/${id}/alarm/cmd`, payload: p, source: 'Web' }];
}
node.warn('Bỏ qua lệnh cloud không hợp lệ: ' + msg.topic);
return null;

// Lệnh từ dashboard (hoặc Web console qua cloud) xuống node (tắt/bật còi, hiệu chuẩn). Không retain: lệnh chỉ có nghĩa lúc gửi.
const id = String(msg.topic).split('/')[1];
const names = { off: 'tắt còi', on: 'bật lại còi' };
const what = (msg.payload && msg.payload.cmd === 'calibrate') ? 'hiệu chuẩn'
    : names[msg.payload] || JSON.stringify(msg.payload);
msg.qos = 1;
msg.retain = false;
return [msg, { payload: { t: Date.now(), text: `📤 ${msg.source === 'Web' ? '[Web] ' : ''}Gửi lệnh ${what} tới ${id}` } }];

// Form cấu hình từ xa → kiểm tra → publish retained flood/<id>/config.
// Node nhận, kiểm tra lại, lưu NVS và trả về sự kiện config_applied / config_rejected.
const id = msg.topic;                         // topic của ui_form = mã node
const ALLOWED = ['H', 'Hmax', 'd0', 't_yellow', 't_red', 't_red_low', 't_yellow_low', 'stable_s', 'period_s'];
const input = msg.payload || {};
const clean = {};
for (const [k, v] of Object.entries(input)) {
    if (!ALLOWED.includes(k)) continue;
    if (v === '' || v === null || v === undefined) continue;
    const n = Number(v);
    if (!isFinite(n)) return [null, { topic: 'Lỗi cấu hình', payload: `Giá trị "${k}" không hợp lệ` }, null];
    clean[k] = n;
}
if (!Object.keys(clean).length) return [null, { topic: 'Cấu hình', payload: 'Chưa nhập giá trị nào' }, null];

const running = ((flow.get('info') || {})[id] || {}).cfg || {};
const stored = (flow.get('cfg') || {})[id] || {};
const c = Object.assign({}, running, stored, clean);

const errs = [];
const has = k => c[k] !== undefined;
if (has('H') && (c.H < 20 || c.H > 450)) errs.push('H phải trong 20–450 cm');
if (has('H') && has('Hmax') && (c.Hmax <= 0 || c.Hmax > c.H)) errs.push('Hmax phải trong (0, H]');
if (has('d0') && (c.d0 < 20 || c.d0 > 450)) errs.push('d0 phải trong 20–450 cm (vùng mù cảm biến)');
if (has('t_yellow') && has('t_red') && !(c.t_yellow > 0 && c.t_yellow < c.t_red)) errs.push('cần 0 < ngưỡng VÀNG < ngưỡng ĐỎ');
if (has('t_red_low') && has('t_red') && has('t_yellow') && !(c.t_red_low >= c.t_yellow && c.t_red_low < c.t_red)) errs.push('cần ngưỡng VÀNG ≤ "ĐỎ→VÀNG" < ngưỡng ĐỎ');
if (has('t_yellow_low') && has('t_yellow') && !(c.t_yellow_low >= 0 && c.t_yellow_low < c.t_yellow)) errs.push('cần 0 ≤ "VÀNG→XANH" < ngưỡng VÀNG');
if (has('period_s') && (c.period_s < 1 || c.period_s > 60)) errs.push('chu kỳ đo 1–60 s');
if (has('stable_s') && (c.stable_s < 0 || c.stable_s > 300)) errs.push('thời gian ổn định 0–300 s');
if (errs.length) return [null, { topic: 'Lỗi cấu hình ' + id, payload: errs.join('; ') }, null];

return [
    { topic: `flood/${id}/config`, payload: c, retain: true, qos: 1 },
    { topic: 'Cấu hình ' + id, payload: 'Đã gửi, chờ node xác nhận…' },
    { payload: { t: Date.now(), text: `⚙️ ${msg.source === 'Web' ? '[Web] ' : ''}Gửi cấu hình tới ${id}: ${JSON.stringify(clean)}` } }
];

// Bảng thiết bị: gộp trạng thái (reg) + heartbeat (info). Node mới tự xuất hiện, không cần sửa flow.
const reg = flow.get('reg') || {}, info = flow.get('info') || {};
const now = Date.now();
const LVN = { green: '🟢 Xanh', yellow: '🟡 Vàng', red: '🔴 Đỏ' };
const ago = t => { if (!t) return '—'; const s = Math.round((now - t) / 1000); return s < 60 ? s + ' s trước' : Math.round(s / 60) + ' phút trước'; };
const upt = s => { if (s === undefined) return '—'; const h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60); return h ? `${h} giờ ${m} phút` : `${m} phút`; };

const ids = Array.from(new Set([...Object.keys(reg), ...Object.keys(info)])).sort();
const rows = ids.map(id => {
    const r = reg[id] || {}, i = info[id] || {};
    const kind = r.kind || (i.role === 'drain' ? 'drain' : i.role === 'road' ? 'road' : '');
    const conn = r.online === false ? '🔴 Offline' : r.stale ? '🟠 Không có dữ liệu'
        : (r.online === true || r.last_seen) ? '🟢 Online' : '⚪ Chưa rõ';
    let reading = '—';
    if (r.data) reading = kind === 'drain'
        ? `${r.data.m} cm · ${r.data.L}% · ${r.data.v >= 0 ? '+' : ''}${r.data.v} cm/ph`
        : `${r.data.h} cm`;
    return {
        id, kind: kind === 'drain' ? 'Cống' : kind === 'road' ? 'Đường' : '?', conn,
        level: LVN[r.level] || '—', reading, last: ago(r.last_seen),
        rssi: i.rssi !== undefined ? i.rssi + ' dBm' : '—', uptime: upt(i.uptime_s),
        err: i.sensor_err !== undefined ? i.sensor_err : '—', fw: i.fw || '—', ip: i.ip || '—'
    };
});
return { payload: rows };

// Gộp dữ liệu hai node vào MỘT lần cập nhật / 15 s (giới hạn kênh miễn phí của ThingSpeak).
// field1 m cống (cm) · field2 L (%) · field3 v (cm/phút) · field4 h đường (cm)
// field5 mức cống · field6 mức đường (0 xanh, 1 vàng, 2 đỏ)
const key = global.get('thingspeak_write_key');
if (!key) { node.status({ fill: 'yellow', shape: 'ring', text: 'Chưa có THINGSPEAK_WRITE_API_KEY' }); return null; }

const reg = flow.get('reg') || {};
const c = reg.cong1, d = reg.duong1;
const code = { green: 0, yellow: 1, red: 2 };
const f = {};
if (c && c.data) { f.field1 = c.data.m; f.field2 = c.data.L; f.field3 = c.data.v; f.field5 = code[c.level]; }
if (d && d.data) { f.field4 = d.data.h; f.field6 = code[d.level]; }
if (!Object.keys(f).length) return null;

const lastSeen = Math.max((c && c.last_seen) || 0, (d && d.last_seen) || 0);
if (lastSeen <= (context.get('lastSeen') || 0)) {
    node.status({ fill: 'grey', shape: 'ring', text: 'Không có dữ liệu mới' });
    return null;
}
context.set('lastSeen', lastSeen);

msg.url = 'https://api.thingspeak.com/update';
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/x-www-form-urlencoded' };
msg.payload = 'api_key=' + encodeURIComponent(key) +
    Object.entries(f).map(([k, v]) => '&' + k + '=' + encodeURIComponent(v)).join('');
node.status({ fill: 'green', shape: 'dot', text: 'Gửi lúc ' + new Date().toLocaleTimeString('vi-VN', { hour12: false }) });
return msg;

// Đọc thông tin bí mật từ biến môi trường (start_all.ps1 nạp từ config/secrets.env).
const chat = env.get('TELEGRAM_CHAT_ID');
const key = env.get('THINGSPEAK_WRITE_API_KEY');
global.set('telegram_chat_id', chat ? String(chat) : null);
global.set('thingspeak_write_key', key || null);
node.status({
    fill: chat && key ? 'green' : 'yellow', shape: 'dot',
    text: `Telegram: ${chat ? 'OK' : 'thiếu chat id'} · ThingSpeak: ${key ? 'OK' : 'thiếu key'}`
});
return null;
